//! Owns the local Node/openhongguo bridge for the lifetime of the desktop app.
//! The child binds to 127.0.0.1 only. A fresh per-launch token is generated by
//! Node's crypto module and passed to Rust over a private startup pipe.
use std::{
    env,
    io::{BufRead, BufReader},
    path::{Path, PathBuf},
    process::{Child, Command, Stdio},
    sync::{mpsc, Mutex},
    thread,
    time::Duration,
};

const READY_TIMEOUT: Duration = Duration::from_secs(20);

pub struct CommunitySidecar {
    child: Mutex<Option<Child>>,
    token: Option<String>,
}

impl CommunitySidecar {
    pub fn start() -> Self {
        match Self::launch() {
            Ok((child, token)) => {
                tracing::info!("managed RedFruit community SDK sidecar started");
                Self {
                    child: Mutex::new(Some(child)),
                    token: Some(token),
                }
            }
            Err(reason) => {
                tracing::warn!(reason, "managed RedFruit community SDK sidecar unavailable");
                Self {
                    child: Mutex::new(None),
                    token: None,
                }
            }
        }
    }

    pub fn token(&self) -> Option<String> {
        self.token.clone()
    }

    pub fn shutdown(&self) {
        let Ok(mut guard) = self.child.lock() else {
            return;
        };
        let Some(mut child) = guard.take() else {
            return;
        };
        stop_child(&mut child);
        tracing::info!("managed RedFruit community SDK sidecar stopped");
    }

    fn launch() -> Result<(Child, String), &'static str> {
        let sdk_dir = find_sdk_dir().ok_or("sdk_assets_missing")?;
        let node = find_node(&sdk_dir).ok_or("node_runtime_missing")?;
        let server = sdk_dir.join("server.mjs");
        let mut child = Command::new(&node)
            .arg(&server)
            .current_dir(&sdk_dir)
            .env("HONGGUORUST_HG3_MANAGED", "1")
            .env_remove("HONGGUORUST_HG2A_EXPERIMENT")
            .env_remove("HONGGUORUST_HG2A_TOKEN")
            .env_remove("HONGGUORUST_HG2A_MEDIA_HOSTS")
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .spawn()
            .map_err(|_| "node_spawn_failed")?;

        let Some(stdout) = child.stdout.take() else {
            stop_child(&mut child);
            return Err("sidecar_stdout_unavailable");
        };
        let Some(stderr) = child.stderr.take() else {
            stop_child(&mut child);
            return Err("sidecar_stderr_unavailable");
        };

        let (ready_tx, ready_rx) = mpsc::channel::<Result<String, &'static str>>();
        thread::spawn(move || {
            let mut reader = BufReader::new(stdout);
            loop {
                let mut line = String::new();
                match reader.read_line(&mut line) {
                    Ok(0) => {
                        let _ = ready_tx.send(Err("sidecar_exited_before_ready"));
                        return;
                    }
                    Ok(_) => {
                        let line = line.trim_end_matches(|ch| ch == '\r' || ch == '\n');
                        if let Some(token) = line.strip_prefix("HG3_READY:") {
                            if valid_ready_token(token) {
                                let _ = ready_tx.send(Ok(token.to_owned()));
                            } else {
                                let _ = ready_tx.send(Err("sidecar_invalid_ready_token"));
                                return;
                            }
                            break;
                        }
                        log_safe_line(line);
                    }
                    Err(_) => {
                        let _ = ready_tx.send(Err("sidecar_stdout_read_failed"));
                        return;
                    }
                }
            }
            for line in reader.lines().filter_map(Result::ok) {
                log_safe_line(&line);
            }
        });

        thread::spawn(move || {
            let reader = BufReader::new(stderr);
            for line in reader.lines().filter_map(Result::ok) {
                log_safe_line(&line);
            }
        });

        let token = match ready_rx.recv_timeout(READY_TIMEOUT) {
            Ok(Ok(token)) => token,
            Ok(Err(reason)) => {
                stop_child(&mut child);
                return Err(reason);
            }
            Err(_) => {
                stop_child(&mut child);
                return Err("sidecar_start_timeout");
            }
        };

        if child.try_wait().ok().flatten().is_some() {
            stop_child(&mut child);
            return Err("sidecar_exited_after_ready");
        }
        Ok((child, token))
    }
}

impl Drop for CommunitySidecar {
    fn drop(&mut self) {
        self.shutdown();
    }
}

fn stop_child(child: &mut Child) {
    if child.try_wait().ok().flatten().is_none() {
        let _ = child.kill();
    }
    let _ = child.wait();
}

fn valid_ready_token(value: &str) -> bool {
    value.len() == 64 && value.bytes().all(|byte| byte.is_ascii_hexdigit())
}

fn log_safe_line(line: &str) {
    // Never forward arbitrary child output: SDK diagnostics can evolve and
    // must not accidentally expose signed URLs, identifiers or session data.
    if line.starts_with("HG2B_COVER_DIAG ") {
        tracing::info!("community cover diagnostics emitted");
    } else if line.starts_with("HG2B_DETAIL_DIAG ") {
        tracing::info!("community detail diagnostics emitted");
    } else if line.starts_with("HG2A_PORT_IN_USE")
        || line.starts_with("HG2A_LISTEN_FAILED")
        || line.starts_with("HG3_STARTUP_ERROR")
        || line.starts_with("HG2A startup failed")
    {
        tracing::warn!("community SDK sidecar reported a startup error");
    }
}

fn has_sdk_runtime(path: &Path) -> bool {
    path.join("server.mjs").is_file()
        && path.join("node_modules/openhongguo/package.json").is_file()
        && path.join("node_modules/libheif-js/package.json").is_file()
        && path.join("node_modules/jpeg-js/package.json").is_file()
        && path
            .join("node_modules/https-proxy-agent/package.json")
            .is_file()
}

fn find_sdk_dir() -> Option<PathBuf> {
    let mut candidates = Vec::new();
    if let Ok(exe) = env::current_exe() {
        if let Some(parent) = exe.parent() {
            candidates.push(parent.join("hg2a-sdk"));
            candidates.push(parent.join("resources").join("hg2a-sdk"));
            candidates.push(parent.join("scripts").join("hg2a-sdk"));
        }
    }
    let manifest_dir = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    if let Some(root) = manifest_dir.parent() {
        candidates.push(root.join("scripts").join("hg2a-sdk"));
    }
    if let Ok(current) = env::current_dir() {
        candidates.push(current.join("scripts").join("hg2a-sdk"));
    }
    candidates.into_iter().find(|path| has_sdk_runtime(path))
}

fn node_version_supported(program: &Path) -> bool {
    let Ok(output) = Command::new(program).arg("--version").output() else {
        return false;
    };
    if !output.status.success() {
        return false;
    }
    let version = String::from_utf8_lossy(&output.stdout);
    version
        .trim()
        .trim_start_matches('v')
        .split('.')
        .next()
        .and_then(|major| major.parse::<u32>().ok())
        .is_some_and(|major| major >= 22)
}

fn find_node(sdk_dir: &Path) -> Option<PathBuf> {
    let mut candidates = Vec::new();
    if let Some(path) = env::var_os("HONGGUORUST_NODE_PATH") {
        candidates.push(PathBuf::from(path));
    }
    if let Ok(exe) = env::current_exe() {
        if let Some(parent) = exe.parent() {
            candidates.push(parent.join("node.exe"));
            candidates.push(parent.join("runtime").join("node.exe"));
        }
    }
    if let Some(parent) = sdk_dir.parent() {
        candidates.push(parent.join("node.exe"));
        candidates.push(parent.join("runtime").join("node.exe"));
    }
    candidates.push(PathBuf::from("node.exe"));
    candidates.push(PathBuf::from("node"));
    candidates.into_iter().find(|candidate| {
        let is_command = candidate.components().count() == 1;
        (is_command || candidate.is_file()) && node_version_supported(candidate)
    })
}

#[cfg(test)]
mod tests {
    use super::valid_ready_token;

    #[test]
    fn startup_token_must_be_a_fresh_256_bit_hex_value() {
        assert!(valid_ready_token(&"a".repeat(64)));
        assert!(valid_ready_token(&"0123456789abcdef".repeat(4)));
        assert!(!valid_ready_token(&"a".repeat(63)));
        assert!(!valid_ready_token(&"g".repeat(64)));
        assert!(!valid_ready_token(&"a".repeat(128)));
    }
}
